/**
 * Silhouette diagrams for each checkpoint position, in the style of a figures sheet:
 * a solid trunk and head with outlined, tapering limbs.
 *
 * All of this is drawn from scratch out of skeleton coordinates, so no artwork from
 * the figures manual is copied or redistributed.
 *
 * Box is 120 x 84 with the water surface at y = 44; smaller y is higher out of the water.
 */

const WATER = 44;
const NS = 'http://www.w3.org/2000/svg';

/** Dolphin circle: the top of the circle sits on the surface. */
const CIRCLE = { cx: 60, cy: 61, r: 17 };

const onCircle = deg => {
  const a = (deg * Math.PI) / 180;
  return [CIRCLE.cx + CIRCLE.r * Math.sin(a), CIRCLE.cy - CIRCLE.r * Math.cos(a)];
};

/** Body wrapped around the dolphin circle, head at the leading edge. */
const arcBody = deg => ({
  head: onCircle(deg + 44),
  headR: 5,
  trunk: [onCircle(deg + 36), onCircle(deg + 22), onCircle(deg + 8)],
  limbs: [{ chain: [onCircle(deg + 8), onCircle(deg - 10), onCircle(deg - 28), onCircle(deg - 42)], w: [7, 5.5, 3.5, 1.4] }],
  guideCircle: true
});

const TRUNK_W = [10.5, 9.5, 8.5];
const LEG_W = [7.5, 5.8, 4, 1.4];

