/**
 * Filled outline through a chain of points, tapering to the given half-widths.
 * Both ends get a rounded cap so limbs finish like a pointed toe rather than a stub.
 */
function ribbon(pts, widths) {
  const n = pts.length;
  const normals = pts.map((_, i) => {
    const prev = pts[Math.max(0, i - 1)];
    const next = pts[Math.min(n - 1, i + 1)];
    const dx = next[0] - prev[0];
    const dy = next[1] - prev[1];
    const m = Math.hypot(dx, dy) || 1;
    return [-dy / m, dx / m];
  });
  const offset = (i, sign) => [
    pts[i][0] + sign * normals[i][0] * widths[i] / 2,
    pts[i][1] + sign * normals[i][1] * widths[i] / 2
  ];
  const dir = (from, to) => {
    const dx = pts[to][0] - pts[from][0];
    const dy = pts[to][1] - pts[from][1];
    const m = Math.hypot(dx, dy) || 1;
    return [dx / m, dy / m];
  };

  const left = pts.map((_, i) => offset(i, 1));
  const right = pts.map((_, i) => offset(i, -1));
  const tail = dir(n - 2, n - 1);
  const nose = dir(1, 0);
  const capEnd = [pts[n - 1][0] + tail[0] * widths[n - 1], pts[n - 1][1] + tail[1] * widths[n - 1]];
  const capStart = [pts[0][0] + nose[0] * widths[0], pts[0][1] + nose[1] * widths[0]];

  const p = xy => `${xy[0].toFixed(2)} ${xy[1].toFixed(2)}`;
  let d = `M ${p(left[0])}`;
  for (let i = 1; i < n; i++) d += ` L ${p(left[i])}`;
  d += ` Q ${p(capEnd)} ${p(right[n - 1])}`;
  for (let i = n - 2; i >= 0; i--) d += ` L ${p(right[i])}`;
  d += ` Q ${p(capStart)} ${p(left[0])} Z`;
  return d;
}

const svgEl = (name, attrs) => {
  const node = document.createElementNS(NS, name);
  for (const [k, v] of Object.entries(attrs)) node.setAttribute(k, v);
  return node;
};

/* ------------------------------------------------------------------ */
/* Angle deviation dial                                                */
/* ------------------------------------------------------------------ */

const DIAL = { cx: 60, cy: 70, r: 54 };

const dialPoint = (deg, r = DIAL.r) => {
  const a = (deg * Math.PI) / 180;
  return [DIAL.cx + r * Math.sin(a), DIAL.cy - r * Math.cos(a)];
};

const dialArc = (from, to, r) => {
  const [x0, y0] = dialPoint(from, r);
  const [x1, y1] = dialPoint(to, r);
  return `M ${x0.toFixed(2)} ${y0.toFixed(2)} A ${r} ${r} 0 0 1 ${x1.toFixed(2)} ${y1.toFixed(2)}`;
};

/**
 * The manual's "visible scales of angle deviation" as a gauge: a plumb line, the
 * 0.2 / 0.5 / 1.0 bands, and a needle at the measured deviation.
 * @param {number} angle Unsigned deviation in degrees
 * @param {[number, number]} tol Small and medium band edges
 */
export function deviationDial(angle, tol = [15, 30]) {
  const [small, medium] = tol;
  const outer = 60;
  const shown = Math.min(outer, Math.abs(angle));
  const band = shown <= small ? 'small' : shown <= medium ? 'medium' : 'large';

  const svg = svgEl('svg', { viewBox: '0 0 120 78', class: 'dial', role: 'img' });
  svg.append(svgEl('title', {}));
  svg.lastChild.textContent = `${angle.toFixed(1)} degrees of deviation — ${band} band`;

  const track = 7;
  svg.append(svgEl('path', { d: dialArc(-outer, -medium, DIAL.r), class: 'dial-band dial-large', 'stroke-width': track }));
  svg.append(svgEl('path', { d: dialArc(-medium, -small, DIAL.r), class: 'dial-band dial-medium', 'stroke-width': track }));
  svg.append(svgEl('path', { d: dialArc(-small, small, DIAL.r), class: 'dial-band dial-small', 'stroke-width': track }));
  svg.append(svgEl('path', { d: dialArc(small, medium, DIAL.r), class: 'dial-band dial-medium', 'stroke-width': track }));
  svg.append(svgEl('path', { d: dialArc(medium, outer, DIAL.r), class: 'dial-band dial-large', 'stroke-width': track }));

  const plumb = dialPoint(0, DIAL.r - 6);
  svg.append(svgEl('line', { x1: DIAL.cx, y1: DIAL.cy, x2: plumb[0], y2: plumb[1], class: 'dial-plumb' }));

  for (const t of [small, medium]) {
    for (const sign of [-1, 1]) {
      const [x0, y0] = dialPoint(sign * t, DIAL.r - 11);
      const [x1, y1] = dialPoint(sign * t, DIAL.r - 4);
      svg.append(svgEl('line', { x1: x0, y1: y0, x2: x1, y2: y1, class: 'dial-tick' }));
    }
  }

  const [nx, ny] = dialPoint(shown, DIAL.r - 12);
  svg.append(svgEl('line', { x1: DIAL.cx, y1: DIAL.cy, x2: nx, y2: ny, class: `dial-needle is-${band}` }));
  svg.append(svgEl('circle', { cx: DIAL.cx, cy: DIAL.cy, r: 3.4, class: `dial-hub is-${band}` }));
  return svg;
}

/**
 * Build an SVG diagram for a pose key.
 * @param {string} key A key of POSES
 * @param {string} [cls] Extra class name for sizing
 */
function technicalArt(key, cls = '') {
  const pose = POSES[key];
  const svg = svgEl('svg', { viewBox: '0 0 120 84', class: ('pose ' + cls).trim(), 'aria-hidden': 'true' });
  if (!pose) return svg;
  if (key === 'balletLeg') {
    svg.removeAttribute('aria-hidden');
    svg.setAttribute('role', 'img');
    svg.setAttribute('aria-label', 'Ballet Leg: body and one leg horizontal at the surface, other leg extended vertically at 90 degrees');
  }


  if (pose.guideCircle) {
    svg.append(svgEl('circle', { cx: CIRCLE.cx, cy: CIRCLE.cy, r: CIRCLE.r, class: 'pose-guide' }));
  }
  const waterY = pose.water ?? WATER;
  svg.append(svgEl('line', { x1: 2, y1: waterY, x2: 118, y2: waterY, class: 'pose-water' }));

  for (const [x, y] of pose.arrows || []) {
    svg.append(svgEl('path', { d: `M ${x} ${y} l 0 12 m -3.5 -5 l 3.5 5 l 3.5 -5`, class: 'pose-arrow' }));
  }
  for (const limb of pose.limbs || []) {
    svg.append(svgEl('path', { d: ribbon(limb.chain, limb.w), class: 'pose-limb' }));
  }
  if (pose.trunk) {
    svg.append(svgEl('path', { d: ribbon(pose.trunk, TRUNK_W), class: 'pose-trunk' }));
  }
  if (pose.head) {
    svg.append(svgEl('circle', { cx: pose.head[0], cy: pose.head[1], r: pose.headR ?? 5.5, class: 'pose-head' }));
  }
  if (key === 'balletLeg') {
    svg.append(svgEl('path', { d: 'M 77 42 V 32 H 67', class: 'pose-guide' }));
    const label = svgEl('text', { x: 80, y: 29, fill: 'currentColor', 'font-size': 9, 'font-family': 'sans-serif' });
    label.textContent = '90°';
    svg.append(label);
  }
  return svg;
}

const CHARACTER_POSES = {
  balletLeg: ['0% 0%', 'Ballet Leg'],
  backLayout: ['0% 0%', 'Back layout'],
  bentKneeBack: ['100% 0%', 'Bent knee back layout'],
  bentKneeVertical: ['0% 100%', 'Bent knee vertical'],
  vertical: ['100% 100%', 'Vertical position']
};

export function poseArt(key, cls = '') {
  const art = CHARACTER_POSES[key];
  if (!art) return technicalArt(key, cls);
  const wrapper = document.createElement('span');
  wrapper.className = 'pose-switch ' + cls;
  const illustration = document.createElement('span');
  illustration.className = 'character-pose';
  illustration.style.backgroundImage = 'url("data:image/png;base64,")';
  illustration.style.backgroundPosition = art[0];
  illustration.style.backgroundSize = '200% auto';
  illustration.style.aspectRatio = key === 'backLayout' || key === 'bentKneeBack' ? '627 / 537' : '627 / 717';
  if (key === 'balletLeg') {
    illustration.style.backgroundImage = 'url("hero-assets/ballet-leg-human.png")';
    illustration.style.backgroundSize = 'contain';
    illustration.style.aspectRatio = '3 / 2';
  }
  illustration.setAttribute('role', 'img');
  illustration.setAttribute('aria-label', art[1] + ' illustrated demonstration');
  const technical = technicalArt(key);
  technical.classList.add('technical-pose');
  wrapper.append(illustration, technical);
  return wrapper;
}
